referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const out = [];
  for (const left of d.left) {
    let matched = false;
    for (const right of d.right)
      if (left[d.leftKey] === right[d.rightKey]) {
        out.push({ left, right });
        matched = true;
      }
    if (!matched && d.kind === "left") out.push({ left, right: null });
  }
  return out;
}

